import json, sqlite3, sys
sys.path.insert(0, "project")
import portal
db = portal.ensure_schema(sqlite3.connect("data/portal.sqlite"))

# 应有的排期（门户同源）：春季 v7 由 service 账本给出，M42-20260327 由门户展开给出
import service
live = {ch: json.load(open(f"scratch/receipts/live-{ch}.json")) for ch in "ABCD"}
vault = {ch: json.load(open(f"input/vault/{ch}-closing-04.json")) for ch in "ABCD"}
held = {}
for ch in "ABCD":
    state = {}
    for batch in vault[ch] + live[ch]:
        state.update(batch.get("rows") or {})
    held[ch] = state

print(f"{'ch':<3}{'uid':<26}{'book':<22}{'held':<22}same")
for ch in "ABCD":
    want = {row["uid"]: row["utc"] for row in service.rows_as_of(db, ch, 7)}
    want["M42-20260327"] = None
    book = json.loads(portal.route(db, "/api/events?from=2026-03-27&to=2026-03-27")[1])
    for row in book:
        if row["uid"] == "M42-20260327":
            want["M42-20260327"] = row["utc"]
    for uid, utc in want.items():
        got = (held[ch].get(uid) or {}).get("utc")
        print(f"{ch:<3}{uid:<26}{str(utc):<22}{str(got):<22}{str(utc)==str(got)}")
print()
print("integrity:", db.execute("pragma integrity_check").fetchone()[0],
      "bookings:", db.execute("select count(*) from bookings").fetchone()[0],
      "versions:", [r[0] for r in db.execute("select version from service_import order by version")])
print("M42-20260327 in portal:", json.loads(portal.route(db, "/api/events?from=2026-03-27&to=2026-03-27")[1]))
db.close()
